GO

-- ============================================================================
-- 8. TABLE: gold.fact_sales
-- TRANSFORMATIONS: One row per order item from silver.order_items joined to silver.orders. Business
--                  keys are swapped for surrogate keys with SSIS Lookups (no match = -1). Delivery
--                  measures are derived ONLY for delivered orders.
-- ----------------------------------------------------------------------------
-- TYPE            : Fact
-- GRAIN           : One row per ORDER ITEM (order_id + order_item_id). The primary key enforces the
--                   grain.
-- SOURCE          : silver.order_items + silver.orders
-- FOREIGN KEYS    : date_key (purchase date), customer_key (version valid at purchase),
--                   product_key, seller_key, order_status_key. Missing matches = -1, never NULL.
-- MEASURES        : price, freight_value, total_item_value; derived: days_to_deliver,
--                   delivery_delay_days, is_late.
-- DERIVED RULES   : days_to_deliver = DATEDIFF(day, order_purchase_ts,
--                   order_delivered_customer_date). delivery_delay_days = DATEDIFF(day,
--                   order_estimated_delivery_date, order_delivered_customer_date); positive = late.
--                   is_late = 1 when delivery_delay_days > 0, else 0.
-- UNDELIVERED     : Orders with no delivered date are KEPT; days_to_deliver, delivery_delay_days
--                   and is_late stay NULL. Q4 and Q8 must exclude them.
-- NEVER           : Put payment_value here: orders have several items AND several payments, so
--                   joining them double counts (fan-out). Payments have their own fact.
-- LOAD RULE       : Truncate (or delete the batch) and reload every run. Never append. Load only
--                   AFTER all dimensions.
-- DQ TESTS        : Test 6 (no orphan FKs) and test 7 (SUM(price) = SUM(silver.order_items.price):
--                   every item must load, even when a lookup fails and returns -1).
-- USED IN         : Q1 to Q5, Q7 and Q8.
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'fact_sales')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[fact_sales]
    (
        [order_id]                      NVARCHAR(50) NOT NULL,  -- degenerate dimension: the order
        [order_item_id]                 INT NOT NULL,           -- item number within the order
        [date_key]                      INT NOT NULL,           -- FK to dim_date: order purchase date
        [customer_key]                  INT NOT NULL,           -- FK to dim_customer: version valid at purchase
        [product_key]                   INT NOT NULL,           -- FK to dim_product
        [seller_key]                    INT NOT NULL,           -- FK to dim_seller (on the item row, not the order)
        [order_status_key]              INT NOT NULL,           -- FK to dim_order_status
        [price]                         DECIMAL(10,2) NULL,     -- item price
        [freight_value]                 DECIMAL(10,2) NULL,     -- freight for the item
        [total_item_value]              DECIMAL(10,2) NULL,     -- price + freight_value
        [order_purchase_ts]             DATETIME2 NULL,         -- kept for the delivery calculations
        [order_delivered_customer_date] DATETIME2 NULL,         -- NULL for undelivered orders
        [order_estimated_delivery_date] DATETIME2 NULL,         -- promised delivery date
        [days_to_deliver]               INT NULL,               -- derived; NULL when undelivered
        [delivery_delay_days]           INT NULL,               -- derived; positive = late; NULL when undelivered
        [is_late]                       BIT NULL,               -- derived; NULL when undelivered
        [dwh_load_ts]                   DATETIME2 NOT NULL CONSTRAINT [df_fact_sales_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]                  INT NULL,               -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_fact_sales] PRIMARY KEY CLUSTERED ([order_id], [order_item_id]),
        CONSTRAINT [fk_fact_sales_dim_date] FOREIGN KEY ([date_key]) REFERENCES [olist_dwh].[gold].[dim_date] ([date_key]),
        CONSTRAINT [fk_fact_sales_dim_customer] FOREIGN KEY ([customer_key]) REFERENCES [olist_dwh].[gold].[dim_customer] ([customer_key]),
        CONSTRAINT [fk_fact_sales_dim_product] FOREIGN KEY ([product_key]) REFERENCES [olist_dwh].[gold].[dim_product] ([product_key]),
        CONSTRAINT [fk_fact_sales_dim_seller] FOREIGN KEY ([seller_key]) REFERENCES [olist_dwh].[gold].[dim_seller] ([seller_key]),
        CONSTRAINT [fk_fact_sales_dim_order_status] FOREIGN KEY ([order_status_key]) REFERENCES [olist_dwh].[gold].[dim_order_status] ([order_status_key])
    );
END
GO

-- ============================================================================
-- 9. TABLE: gold.fact_payments
-- TRANSFORMATIONS: One row per payment line from silver.order_payments joined to silver.orders (for
--                  the customer and the purchase date). Business keys are swapped for surrogate
--                  keys with SSIS Lookups (no match = -1).
-- ----------------------------------------------------------------------------
-- TYPE            : Fact
-- GRAIN           : One row per PAYMENT LINE per order (order_id + payment_sequential). The primary
--                   key enforces the grain.
-- SOURCE          : silver.order_payments + silver.orders
-- FOREIGN KEYS    : date_key (order purchase date), customer_key (version valid at purchase),
--                   payment_type_key. Missing matches = -1, never NULL.
-- MEASURES        : payment_value, payment_installments.
-- NEVER           : Join this fact directly to fact_sales on order_id: an order with 2 items and 2
--                   payments would give 4 rows and double count. Aggregate each fact separately.
-- LOAD RULE       : Truncate (or delete the batch) and reload every run. Never append. Load only
--                   AFTER all dimensions.
-- DQ TESTS        : Test 6 (no orphan FKs) and test 8 (SUM(payment_value) =
--                   SUM(silver.order_payments.payment_value)).
-- USED IN         : Q6 (payment type mix by revenue and average installments).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'fact_payments')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[fact_payments]
    (
        [order_id]             NVARCHAR(50) NOT NULL,  -- degenerate dimension: the order
        [payment_sequential]   INT NOT NULL,           -- payment line number within the order
        [date_key]             INT NOT NULL,           -- FK to dim_date: order purchase date
        [customer_key]         INT NOT NULL,           -- FK to dim_customer: version valid at purchase
        [payment_type_key]     INT NOT NULL,           -- FK to dim_payment_type
        [payment_installments] INT NULL,               -- number of installments
        [payment_value]        DECIMAL(10,2) NULL,     -- payment amount
        [dwh_load_ts]          DATETIME2 NOT NULL CONSTRAINT [df_fact_payments_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]         INT NULL,               -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_fact_payments] PRIMARY KEY CLUSTERED ([order_id], [payment_sequential]),
        CONSTRAINT [fk_fact_payments_dim_date] FOREIGN KEY ([date_key]) REFERENCES [olist_dwh].[gold].[dim_date] ([date_key]),
        CONSTRAINT [fk_fact_payments_dim_customer] FOREIGN KEY ([customer_key]) REFERENCES [olist_dwh].[gold].[dim_customer] ([customer_key]),
        CONSTRAINT [fk_fact_payments_dim_payment_type] FOREIGN KEY ([payment_type_key]) REFERENCES [olist_dwh].[gold].[dim_payment_type] ([payment_type_key])
    );
END
GO

-- ============================================================================
-- 10. TABLE: gold.fact_reviews
-- TRANSFORMATIONS: One row per review from silver.order_reviews (already de-duplicated on
--                  review_id) joined to silver.orders (for the customer). Business keys are swapped
--                  for surrogate keys with SSIS Lookups (no match = -1).
-- ----------------------------------------------------------------------------
-- TYPE            : Fact
-- GRAIN           : One row per REVIEW (review_id). The primary key enforces the grain.
-- SOURCE          : silver.order_reviews + silver.orders
-- FOREIGN KEYS    : date_key (review creation date), customer_key (version valid at the order's
--                   purchase). Missing matches = -1, never NULL.
-- MEASURES        : review_score (1 to 5).
-- IMPORTANT       : Reviews are ORDER-level, not item-level. To attribute a review to a seller (Q3)
--                   or to late delivery (Q8), go through the DISTINCT (order_id, seller_key) pairs
--                   in fact_sales. Never join reviews straight onto item rows: that double counts.
-- LOAD RULE       : Truncate (or delete the batch) and reload every run. Never append. Load only
--                   AFTER all dimensions.
-- DQ TESTS        : Test 6 (no orphan FKs).
-- USED IN         : Q3 (average review score per seller) and Q8 (late vs on-time review scores).
-- ============================================================================
IF NOT EXISTS (SELECT 1
               FROM [olist_dwh].[sys].[tables]  AS t
               JOIN [olist_dwh].[sys].[schemas] AS s ON s.[schema_id] = t.[schema_id]
               WHERE s.[name] = N'gold' AND t.[name] = N'fact_reviews')
BEGIN
    CREATE TABLE [olist_dwh].[gold].[fact_reviews]
    (
        [review_id]               NVARCHAR(50) NOT NULL,  -- business key of the review
        [order_id]                NVARCHAR(50) NOT NULL,  -- degenerate dimension: the order reviewed
        [date_key]                INT NOT NULL,           -- FK to dim_date: review creation date
        [customer_key]            INT NOT NULL,           -- FK to dim_customer: version valid at purchase
        [review_score]            TINYINT NULL,           -- 1 to 5
        [review_creation_date]    DATETIME2 NULL,         -- survey sent
        [review_answer_timestamp] DATETIME2 NULL,         -- survey answered
        [dwh_load_ts]             DATETIME2 NOT NULL CONSTRAINT [df_fact_reviews_dwh_load_ts] DEFAULT SYSDATETIME(),  -- load time, set by SQL Server
        [dwh_batch_id]            INT NULL,               -- run id from etl.batch_log, set by SSIS
        CONSTRAINT [pk_fact_reviews] PRIMARY KEY CLUSTERED ([review_id]),
        CONSTRAINT [fk_fact_reviews_dim_date] FOREIGN KEY ([date_key]) REFERENCES [olist_dwh].[gold].[dim_date] ([date_key]),
        CONSTRAINT [fk_fact_reviews_dim_customer] FOREIGN KEY ([customer_key]) REFERENCES [olist_dwh].[gold].[dim_customer] ([customer_key])
    );
END
GO
